import pyomo.environ as pyo

DATA = {
    "bones": ["small", "large"],
    "medication_available": 2000,        # units of tooth medication
    "medication_per_bone": {"small": 10, "large": 15},
    "meat_per_bone": {"small": 12, "large": 15},
    "small_share_min": 0.5,              # at least 50% of bones must be small
    "large_min": 30,                     # at least 30 large bones
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.BONES = pyo.Set(initialize=d["bones"])

    # Decision: number of each bone type to make (indivisible -> integers)
    model.bones_made = pyo.Var(
        model.BONES,
        domain=pyo.NonNegativeIntegers,
        bounds=(0, None),
    )

    # Objective: minimize total meat used
    def obj_rule(m):
        return sum(d["meat_per_bone"][b] * m.bones_made[b] for b in m.BONES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Tooth medication availability
    def medication_limit_rule(m):
        return sum(
            d["medication_per_bone"][b] * m.bones_made[b] for b in m.BONES
        ) <= d["medication_available"]

    model.medication_limit = pyo.Constraint(rule=medication_limit_rule)

    # At least 50% of bones must be small: small >= 0.5*(small + large)
    # linearised: (1 - 0.5)*small - 0.5*large >= 0
    def small_share_rule(m):
        return (
            (1 - d["small_share_min"]) * m.bones_made["small"]
            - d["small_share_min"] * m.bones_made["large"]
        ) >= 0

    model.small_share = pyo.Constraint(rule=small_share_rule)

    # At least 30 large bones
    def large_min_rule(m):
        return m.bones_made["large"] >= d["large_min"]

    model.large_min = pyo.Constraint(rule=large_min_rule)

    return model


